CREATE TABLE vital_signs(id uuid PRIMARY KEY,encounter_id uuid NOT NULL,observation text NOT NULL,recorded_by uuid NOT NULL,systolic numeric(7,2),diastolic numeric(7,2),pulse numeric(7,2),temperature numeric(7,2),oxygen_saturation numeric(7,2),weight numeric(7,2),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO vital_signs(id,encounter_id,observation,recorded_by,systolic,diastolic,pulse,temperature,oxygen_saturation,weight,version,created_at) SELECT id,nullif(data->>'encounterId','')::uuid,data->>'observation',nullif(data->>'recordedBy','')::uuid,coalesce(nullif(data->>'systolic','')::numeric,0),coalesce(nullif(data->>'diastolic','')::numeric,0),coalesce(nullif(data->>'pulse','')::numeric,0),coalesce(nullif(data->>'temperature','')::numeric,0),coalesce(nullif(data->>'oxygenSaturation','')::numeric,0),coalesce(nullif(data->>'weight','')::numeric,0),version,created_at FROM records WHERE kind='vitals';

ALTER TABLE vital_signs ADD FOREIGN KEY(encounter_id) REFERENCES encounters(id);CREATE INDEX vitals_encounter ON vital_signs(encounter_id,created_at);
